            C++

    #include <iostream>
#include <vector>
using namespace std;

bool areAnagrams(string &s1, string &s2) {

    if (s1.length() != s2.length()) return false;

    // for lowercase a-z
    vector<int> freq(26, 0);  

    // Count frequency of each character in s1
    for(char ch : s1) 
        freq[ch - 'a']++;

    // Subtract frequency using characters from s2
    for(char ch : s2) 
        freq[ch - 'a']--;

    // If any count is not zero, not an anagram
    for(int count : freq) {
        if (count != 0)
            return false;
    }

    return true;
}

int main() {

    string s1 = "geeks";
    string s2 = "kseeg";

    if (areAnagrams(s1, s2))
        cout << "true" << endl;
    else
        cout << "false" << endl;

    return 0;
}


